 1→/**
 2→ * Independent reachability probe — the "independent validator" the outcome
 3→ * judge needs before it may call an asset wrong.
 4→ *
 5→ * A model's call timing out at an address proves the model followed the
 6→ * asset that gave it the address. It does not prove the address is wrong: the
 7→ * right address can time out once. So the harness itself opens a TCP
 8→ * connection to every host:port the run attempted and records the result.
 9→ * The judge treats a failed call as `corrected(wrong)` only when this probe
10→ * also failed to reach the address; when the probe reaches it, the model's
11→ * failure was environmental and the outcome is `needs_review`.
12→ *
13→ * The record says when it was taken and by whom (`source`). A probe taken at
14→ * run time can speak to the state at run time; one taken afterwards can only
15→ * say the address is persistently unreachable or reachable now, and the judge
16→ * carries that wording through.
17→ *
18→ * Usage:
19→ *   node probe-reachability.mjs --verdict=verdict.json --out=reachability.json [--source="harness probe at run time"] [--timeout-ms=5000]
20→ *   node probe-reachability.mjs --targets=10.244.7.19:8096,127.0.0.1:47318 --out=reachability.json
21→ */
22→
23→import { readFileSync, writeFileSync } from "node:fs";
24→import { connect } from "node:net";
25→
26→/** TCP-connect once; resolves {ok, why, elapsed_ms}. Never rejects. */
27→export function probe(host, port, { timeoutMs = 5000 } = {}) {
28→  return new Promise((resolve) => {
29→    const started = Date.now();
30→    let done = false;
31→    const finish = (ok, why) => {
32→      if (done) return;
33→      done = true;
34→      try { socket.destroy(); } catch { /* already closed */ }
35→      resolve({ ok, why, elapsed_ms: Date.now() - started });
36→    };
37→    const socket = connect({ host, port: Number(port) });
38→    socket.setTimeout(timeoutMs);
39→    socket.once("connect", () => finish(true, "tcp connect ok"));
40→    socket.once("timeout", () => finish(false, "timed out"));
41→    socket.once("error", (err) => finish(false, err?.code === "ECONNREFUSED" ? "could not connect" : `error ${err?.code ?? err?.message ?? "unknown"}`));
42→  });
43→}
44→
45→/** Distinct host:port targets from a verdict's attempts. */
46→export function targetsOf(verdictDoc) {
47→  const seen = new Set();
48→  for (const a of verdictDoc?.attempts ?? []) {
49→    if (a?.host && a?.port) seen.add(`${a.host}:${a.port}`);
50→  }
51→  return [...seen];
52→}
53→
54→export async function probeAll(targets, { timeoutMs = 5000, source = "harness probe" } = {}) {
55→  const checkedAt = new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
56→  const out = {};
57→  for (const t of targets) {
58→    const i = t.lastIndexOf(":");
59→    const host = t.slice(0, i), port = t.slice(i + 1);
60→    const r = await probe(host, port, { timeoutMs });
61→    out[t] = { ...r, checked_at: checkedAt, source, timeout_ms: timeoutMs };
62→  }
63→  return { checked_at: checkedAt, source, timeout_ms: timeoutMs, targets: out };
64→}
65→
66→if (import.meta.url === `file://${process.argv[1]}`) {
67→  const args = process.argv.slice(2);
68→  const arg = (n) => { const a = args.find((x) => x.startsWith(`--${n}=`)); return a ? a.slice(n.length + 3) : null; };
69→  const out = arg("out");
70→  if (!out || (!arg("verdict") && !arg("targets"))) {
71→    console.error("usage: node probe-reachability.mjs (--verdict=F | --targets=h:p,...) --out=F [--source=S] [--timeout-ms=N]");
72→    process.exit(2);
73→  }
74→  const targets = arg("targets") ? arg("targets").split(",").filter(Boolean) : targetsOf(JSON.parse(readFileSync(arg("verdict"), "utf8")));
75→  const record = await probeAll(targets, { timeoutMs: Number(arg("timeout-ms") ?? 5000), source: arg("source") ?? "harness probe" });
76→  writeFileSync(out, JSON.stringify(record, null, 2) + "\n");
77→  for (const [t, r] of Object.entries(record.targets)) console.log(`${t}: ${r.ok ? "reachable" : "unreachable"} (${r.why}, ${r.elapsed_ms} ms)`);
78→  if (targets.length === 0) console.log("no targets to probe");
79→}
80→

 1→import { test } from "node:test";
 2→import assert from "node:assert/strict";
 3→import { planVisibility, renderPlan, HIDDEN } from "./plan-visibility.mjs";
 4→
 5→const WRONG = "skl-sZFb3KatWY6m", RIGHT = "skl-oBaDO5CceKnr", PEND = "skl-pending";
 6→
 7→const baseline = {
 8→  assets: {
 9→    [WRONG]: { baseline_visibility: "team" },
10→    [RIGHT]: { baseline_visibility: "team" },
11→    [PEND]: { baseline_visibility: "team" },
12→  },
13→  decisions: [
14→    { asset_id: WRONG, decision: "reject", reasons: ["rule reject: a corrected record exists (reason=wrong)"] },
15→    { asset_id: RIGHT, decision: "admit", reasons: ["rule admit"] },
16→    { asset_id: PEND, decision: "pending", reasons: ["cold start"] },
17→  ],
18→};
19→
20→test("apply from the baseline: only the rejected asset changes, to private", () => {
21→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" } });
22→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.from, c.to]), [[WRONG, "team", HIDDEN]]);
23→  assert.match(plan.changes[0].because, /reject → private/);
24→  assert.equal(plan.unchanged.length, 2);
25→  assert.ok(plan.unchanged.find((u) => u.asset_id === PEND).because.includes("does not hide what it could not judge"));
26→  assert.deepEqual(plan.unreadable, []);
27→});
28→
29→test("apply is idempotent: already-private rejected asset is unchanged", () => {
30→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: "team", [PEND]: "team" } });
31→  assert.deepEqual(plan.changes, []);
32→});
33→
34→test("reset restores the baseline regardless of decisions", () => {
35→  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: HIDDEN, [PEND]: "team" } });
36→  const byId = (a, b) => a[0].localeCompare(b[0]);
37→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.to]).sort(byId), [[WRONG, "team"], [RIGHT, "team"]].sort(byId));
38→  assert.ok(plan.changes.every((c) => /reset to baseline/.test(c.because)));
39→});
40→
41→test("an asset whose visibility could not be read is reported, not planned", () => {
42→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: null, [RIGHT]: "team" } });
43→  assert.deepEqual(plan.unreadable.sort(), [PEND, WRONG].sort());
44→  assert.deepEqual(plan.changes, []);
45→  assert.match(renderPlan(plan), /could not be read — NOT planned/);
46→});
47→
48→test("an asset in the baseline with no decision keeps the baseline and is listed as undecided", () => {
49→  const b = { assets: { [RIGHT]: { baseline_visibility: "team" } }, decisions: [] };
50→  const plan = planVisibility({ mode: "apply", baseline: b, current: { [RIGHT]: HIDDEN } });
51→  assert.deepEqual(plan.undecided, [RIGHT]);
52→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.to]), [[RIGHT, "team"]]);
53→});
54→
55→test("unknown mode throws", () => {
56→  assert.throws(() => planVisibility({ mode: "nuke", baseline, current: {} }), /mode must be/);
57→});
58→
59→test("render lists changes and unchanged, or says nothing to change", () => {
60→  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" } });
61→  assert.match(renderPlan(plan), /nothing to change/);
62→});
63→
64→test("hide mode: named assets private, everything else at baseline, decisions ignored", () => {
65→  const plan = planVisibility({ mode: "hide", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" }, hide: [RIGHT] });
66→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.from, c.to]), [[RIGHT, "team", HIDDEN]]);
67→  assert.match(plan.changes[0].because, /leave-one-out: hidden/);
68→  // the rejected asset is NOT hidden in hide mode — decisions are not applied
69→  assert.ok(plan.unchanged.find((u) => u.asset_id === WRONG));
70→});
71→
72→test("hide mode refuses an empty list or an id outside the baseline", () => {
73→  assert.throws(() => planVisibility({ mode: "hide", baseline, current: {}, hide: [] }), /at least one/);
74→  assert.throws(() => planVisibility({ mode: "hide", baseline, current: {}, hide: ["skl-nope"] }), /not in the baseline/);
75→});
