758→export async function handleFilesRead(body: unknown, _auth: V2AuthContext, requestId: string, deps: SkillRouterDeps): Promise<ApiResponseEnvelope> {
759→  const t0 = Date.now();
760→  const pre = await precheck(filesReadRequestSchema, body, _auth, deps, requestId);
761→  if (!pre.ok) { obsLogger.warn("skill.handleFilesRead.done", { req_id: requestId, code: pre.envelope.code, dur_ms: Date.now() - t0, reason: "precheck" }); return pre.envelope; }
762→  try {
763→    const targetF = await headOf(pre.core, pre.data);
764→    const admF = await admissionFilter([targetF], { deps, auth: _auth, user_id: pre.data.user_id, team_id: pre.data.team_id, agent_id: pre.data.agent_id });
765→    if (admF.allowed.length === 0) return notAdmitted(pre.data.skill_id, admF.denied[0]?.reason ?? "unknown", requestId);
766→    // Read the version that was checked, not whatever is head by now.
767→    const r = await pre.core.readFile({ ...pre.data, version: targetF.version ?? pre.data.version });
768→    obsLogger.info("skill.handleFilesRead.done", { req_id: requestId, code: 0, dur_ms: Date.now() - t0, skill_id: pre.data.skill_id,
769→      version: r.version,
770→      size_bytes: r.size_bytes,
771→      encoding: r.encoding, });
772→    return successEnvelope(r, requestId);
773→  } catch (e) { obsLogger.error("skill.handleFilesRead.done", { req_id: requestId, dur_ms: Date.now() - t0, skill_id: pre.data.skill_id }, e instanceof Error ? e : undefined); return mapCoreError(e, requestId); }
