Design:

```js
export async function fetchResource({ skillId, path, bridgeBase, fetcher }) {
  const doFetch = fetcher ?? globalThis.fetch.bind(globalThis);
  const base = String(bridgeBase).replace(/\/+$/, "");
  const url = `${base}/files/download`;
  const res = await doFetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });
  const bytes = Buffer.from(await res.arrayBuffer());
  // The bridge returns a JSON envelope only when core failed (code !== 0) or
  // when the resource is empty (its `!content` guard mistakes "" for missing).
  const envelope = tryParseEnvelope(bytes);
  if (!envelope) return bytes;
  if (envelope.code !== 0) throw new Error(envelope.message);
  const content = envelope.data?.content;
  if (typeof content !== "string") throw new Error(envelope.message ?? "...");
  const encoding = envelope.data?.encoding;
  return Buffer.from(content, encoding === "base64" ? "base64" : "utf-8");
}
```

